contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint initialSeedFunds) public payable {
        require(address(this).balance >= 10);
        // Optionally let the test contract hold extra ether from the start (harmless setup).
        if (initialSeedFunds > 0) {
            initialSeedFunds = 0;
        }
        uint potBefore = c.pot();
        uint balBefore = address(this).balance;
        c.play{value: 10}();
        uint potAfter = c.pot();
        // General rule: a non-winning play (pot != 0) must not move any ether to the caller;
        // a winning play (pot == 0) must pay the caller exactly the full pot (potBefore + 10
        // contributed in this call, since bank and player are both this contract in deployment).
        assert(potAfter != 0 || address(this).balance == balBefore + potBefore + 10);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(address(this).balance >= 10);
        uint potBefore = c.pot();
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;
        c.play{value: 10}();
        uint potAfter = c.pot();
        // Rule: on a loss (pot still nonzero) no ether moves inside C, so the pot
        // grows by exactly 10, C's balance grows by exactly 10 and the caller's
        // balance shrinks by exactly 10 (only the ticket was deposited).
        assert(potAfter == 0 || (potAfter == potBefore + 10 && address(c).balance == cBalBefore + 10 && address(this).balance == myBalBefore - 10));
    }
    receive() external payable {}
}

